    for (const [i, f] of this.P.entries()) if (f.combo >= 2 && f.comboT > 0) { const s = ` ${f.combo} HIT `; fb.text(i === 0 ? 1 : W - s.length - 1, 2, s, f.combo >= 5 ? 0x1a0a00 : C.gold2, f.combo >= 5 ? C.gold2 : 0x1a1408) }
