  // ── the select screens: carousel (any pane), draft grid, tiers ───────────
  private drawSelect() {
    const g = this.g, fb = g.fb, W = g.W, H = g.H, R = fb.rows, t = g.t
    fb.darken(0, 0, W, H, 0.3)
    const L = this.list()
