    fb.textC(R - 2, ` ${st.name}: C ${st.sp.name} · X ${st.su.name} `, 0xe6e8f5, 0x0b0d18)
    fb.textC(R - 1, ' ←→↑↓ browse · SPACE draft / drop · A movie trio · B back ', C.dim, 0x0b0d18)
  }
  private drawMatch() {
    const g = this.g, fb = g.fb, W = g.W, H = g.H, R = fb.rows
