    const fl = 8 + k * 20 + (hs(Math.floor(t * 40)) * 5)
    for (let i = 0; i < fl; i++) { const a = 1 - i / fl; for (const r of [4, 5]) lit(cv, y0, x - i * 1.1, r, i < 4 ? 0xffffff : i < 10 ? 0xffe27a : 0xff8a30, 0.95 * a) }
    speed(cv, y0, x - 30, 0xffd9a0, 0.8 * k, t)
