    if (d > 0) { gy = Math.min(LH - 7, 3 + 40 * d * d); const bn = Math.abs(Math.sin(d * 6)) * 3 * Math.exp(-d * 2.5); if (gy >= LH - 7) gy = LH - 7 - bn; gx += d * 8 * Math.exp(-d * 2) }
