  if (t >= 4.7 && !calm) for (let i = 0; i < 3; i++) { const k = ((t * 1.1 + i * 0.33) % 1); plus(cv, y0, x + 6 + i * 5, y - k * 5, 0x8a86a8, 0.7 * (1 - k)) }
