    if (!calm && t >= 4.9 && t < 5.6) lx = xl - 28 + 28 * seg(t, 4.9, 5.6)
    const bow = !calm && t >= 6.4 && t < 7.4
    if (!calm && t < 4.3 && ap < 1) { rad(cv, y0, (xl + 12) / 2, y0 + 6, 9 * (1 - ap) + 3, 0x58e6ff, 0.6 * (1 - ap)); if (hs(Math.floor(t * 20)) < 0.5) { /* flicker-in */ } }
