const UTT = 8
LANES.ultron = (cv, y0, t0, calm) => {
  const W = cv.W, t = calm ? 5.2 : t0 % UTT, cx = Math.round(W * 0.5), bx = cx - 14
  ground(cv, y0)
  const bodyA = calm ? 1 : seg(t, 3.3, 3.7)
