const VP = { o: 0x3a0c24, r: 0xd02e55, h: 0xff8a96, y: 0xffe94d, Y: 0xd9a81c, e: 0x2cb06c, n: 0x146a40, g: 0xf7c948, w: 0xfff4c0, d: 0x86193f }
