STAGES.warmachine = (cv, t, calm) => {
  const pu = calm ? 0.5 : 0.5 + 0.5 * Math.sin(t * 3), br = !calm && Math.sin(t * 1.8) > 0.5 ? -1 : 0
  cv.radial(14, 5, 8, 0x4a78c8, 0.12 + 0.1 * pu)
